CREATE FUNCTION public.increment_field_usage(p_tenant_id character varying, p_schema_id uuid, p_field_id character varying, p_increment integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    VALUES (p_tenant_id, p_schema_id, p_field_id, p_increment)
    ON CONFLICT (tenant_id, schema_id, field_id)
    DO UPDATE SET
        usage_count = identity_field_statistics.usage_count + EXCLUDED.usage_count,
        updated_at = NOW();
END;
$$;


