CREATE FUNCTION public.notify_user_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    notification JSON;
BEGIN
    notification = json_build_object(
        'operation', TG_OP,
        'table', TG_TABLE_NAME,
        'userId', CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
        'tenantId', CASE WHEN TG_OP = 'DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END,
        'timestamp', extract(epoch from now()) * 1000
    );
    PERFORM pg_notify('user_changes', notification::text);
    IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


