    IF OLD.status IS DISTINCT FROM NEW.status THEN
        PERFORM increment_field_usage(OLD.tenant_id, OLD.primary_schema_id, 'status', -1);
        PERFORM increment_field_usage(NEW.tenant_id, NEW.primary_schema_id, 'status', 1);
    END IF;
    FOR all_keys IN SELECT DISTINCT k FROM (SELECT jsonb_object_keys(COALESCE(OLD.core_attributes, '{}'::jsonb)) AS k UNION SELECT jsonb_object_keys(COALESCE(NEW.core_attributes, '{}'::jsonb)) AS k) AS all_keys_sub LOOP
