        new_val := NEW.core_attributes -> all_keys;
        IF jsonb_typeof(old_val) != 'null' AND (jsonb_typeof(new_val) = 'null' OR new_val IS NULL) THEN
            PERFORM increment_field_usage(OLD.tenant_id, OLD.primary_schema_id, all_keys, -1);
        ELSIF (jsonb_typeof(old_val) = 'null' OR old_val IS NULL) AND jsonb_typeof(new_val) != 'null' THEN
            PERFORM increment_field_usage(NEW.tenant_id, NEW.primary_schema_id, all_keys, 1);
        END IF;
    END LOOP;
    FOR all_keys IN SELECT DISTINCT k FROM (SELECT jsonb_object_keys(COALESCE(OLD.extended_attributes, '{}'::jsonb)) AS k UNION SELECT jsonb_object_keys(COALESCE(NEW.extended_attributes, '{}'::jsonb)) AS k) AS all_keys_sub LOOP
        old_val := OLD.extended_attributes -> all_keys;
        new_val := NEW.extended_attributes -> all_keys;
        IF jsonb_typeof(old_val) != 'null' AND (jsonb_typeof(new_val) = 'null' OR new_val IS NULL) THEN
            PERFORM increment_field_usage(OLD.tenant_id, OLD.primary_schema_id, all_keys, -1);
        ELSIF (jsonb_typeof(old_val) = 'null' OR old_val IS NULL) AND jsonb_typeof(new_val) != 'null' THEN
