-- TOC entry 334 (class 1255 OID 34316)
-- Name: update_extended_attribute_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_extended_attribute_usage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tenant_id VARCHAR;
    v_system_key VARCHAR;
BEGIN
    -- On INSERT, we increment the count.
    IF (TG_OP = 'INSERT') THEN
        -- Get the tenant_id from the parent 'identities' table.
        SELECT tenant_id INTO v_tenant_id FROM identities WHERE identity_id = NEW.identity_id;

        -- Get the system_key from the extended_attribute_definitions table
        SELECT system_key INTO v_system_key FROM extended_attribute_definitions WHERE id = NEW.definition_id;

        -- Insert a new stats record or update the existing one on conflict.
        -- Use the definition_id as both schema_id and field_id for now
        VALUES (v_tenant_id, NEW.definition_id, v_system_key, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        ON CONFLICT (tenant_id, schema_id, field_id)
        DO UPDATE SET
            usage_count = identity_field_statistics.usage_count + 1,
            updated_at = CURRENT_TIMESTAMP;
        RETURN NEW;
    END IF;

    -- On DELETE, we decrement the count.
    IF (TG_OP = 'DELETE') THEN
        -- Get the tenant_id from the parent 'identities' table.
        SELECT tenant_id INTO v_tenant_id FROM identities WHERE identity_id = OLD.identity_id;

        -- Get the system_key from the extended_attribute_definitions table
        SELECT system_key INTO v_system_key FROM extended_attribute_definitions WHERE id = OLD.definition_id;

        -- Decrement the usage count for the corresponding definition.
        UPDATE identity_field_statistics
        SET
            usage_count = usage_count - 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE tenant_id = v_tenant_id AND schema_id = OLD.definition_id AND field_id = v_system_key;
        RETURN OLD;
    END IF;

    RETURN NULL; -- Should not happen for INSERT/DELETE triggers
END;
$$;


