    CONSTRAINT workflow_approvals_approver_type_check CHECK (((approver_type)::text = ANY ((ARRAY['MANAGER'::character varying, 'APP_OWNER'::character varying, 'ROLE_OWNER'::character varying, 'SPECIFIC'::character varying, 'DYNAMIC'::character varying])::text[]))),
    CONSTRAINT workflow_approvals_decision_check CHECK (((decision)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'TIMEOUT'::character varying, 'DELEGATED'::character varying])::text[])))
);


