--
-- TOC entry 294 (class 1259 OID 107144)
-- Name: workflows; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.workflows (
    id uuid NOT NULL,
    application_scope jsonb,
    category character varying(255),
    compliance_frameworks jsonb,
    created_at timestamp(6) with time zone NOT NULL,
    created_by uuid,
    cron_schedule character varying(255),
    description text,
    drift_detected boolean,
    edges jsonb NOT NULL,
    event_config jsonb,
    has_sod_violation boolean,
    has_time_logic boolean,
    is_connected_to_template boolean,
    last_modified_by uuid,
    last_synced_at timestamp(6) with time zone,
    name character varying(255) NOT NULL,
    nodes jsonb NOT NULL,
    permissions jsonb,
    policy_compliance character varying(255),
    risk_score integer,
    role_sensitivity character varying(255),
    source_template_id uuid,
    status character varying(255) NOT NULL,
    tags jsonb,
    template_metadata jsonb,
    trigger_type character varying(255),
    updated_at timestamp(6) with time zone,
    upstream_version character varying(255),
    version character varying(255) NOT NULL,
    CONSTRAINT workflows_category_check CHECK (((category)::text = ANY ((ARRAY['JOINER_MOVER_LEAVER'::character varying, 'ACCESS_REQUEST'::character varying, 'CERTIFICATION'::character varying, 'REVOCATION'::character varying, 'EXCEPTION'::character varying, 'AI_RISK'::character varying])::text[]))),
    CONSTRAINT workflows_policy_compliance_check CHECK (((policy_compliance)::text = ANY ((ARRAY['COMPLIANT'::character varying, 'WARNING'::character varying, 'VIOLATION'::character varying])::text[]))),
    CONSTRAINT workflows_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 10))),
    CONSTRAINT workflows_role_sensitivity_check CHECK (((role_sensitivity)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying])::text[]))),
    CONSTRAINT workflows_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'DEPRECATED'::character varying])::text[]))),
    CONSTRAINT workflows_trigger_type_check CHECK (((trigger_type)::text = ANY ((ARRAY['EVENT_BASED'::character varying, 'TIME_BASED'::character varying, 'MANUAL'::character varying])::text[])))
);


ALTER TABLE public.workflows OWNER TO postgres;

