4a69f798-c490-4bdf-b596-5244b47e14a6	9a8b7c6d-5e4f-3210-9876-543210fedcba	kyadmin	user	{"message": "update template_manager: Assign role", "ipAddress": "10.0.1.18", "userAgent": "node", "identifier": "kyadmin"}	\N	update	null	{"language": "EN_UK", "emailBody": "<!DOCTYPE html>\\n<html lang=\\"en\\" style=\\"margin:0;padding:0;\\">\\n<head>\\n  <meta charset=\\"UTF-8\\" />\\n  <meta name=\\"viewport\\" content=\\"width=device-width\\" />\\n  <meta http-equiv=\\"X-UA-Compatible\\" content=\\"IE=edge\\" />\\n  <title>AIdentX Notification</title>\\n  <style>\\n    /* Some clients respect embedded CSS for dark mode */\\n    @media (prefers-color-scheme: dark) {\\n      .bg-body { background-color:#0f1a1a !important; }\\n      .card     { background-color:#112424 !important; border-color:#1f3a3a !important; }\\n      .text     { color:#e6f6f6 !important; }\\n      .muted    { color:#b8d8d8 !important; }\\n      .divider  { border-color:#245c5c !important; }\\n      .btn      { color:#ffffff !important; }\\n      .logo-txt { color:#e6f6f6 !important; }\\n    }\\n  </style>\\n</head>\\n<body class=\\"bg-body\\" style=\\"margin:0;padding:0;background:#f4f7fb;\\">\\n  <!-- Full-width wrapper -->\\n  <table role=\\"presentation\\" cellpadding=\\"0\\" cellspacing=\\"0\\" border=\\"0\\" width=\\"100%\\" style=\\"background:#f4f7fb;\\">\\n    <tr>\\n      <td align=\\"center\\" style=\\"padding:24px 12px;\\">\\n        <!-- Main container -->\\n        <table role=\\"presentation\\" cellpadding=\\"0\\" cellspacing=\\"0\\" border=\\"0\\" width=\\"600\\" class=\\"card\\" style=\\"width:600px;max-width:100%;background:#ffffff;border-radius:12px;border:1px solid #e6eef5;\\">\\n          <!-- Header -->\\n          <tr>\\n            <td style=\\"border-top-left-radius:12px;border-top-right-radius:12px;background:linear-gradient(135deg,#348B8B, #448BC5);padding:24px 24px;\\">\\n              <table role=\\"presentation\\" width=\\"100%\\">\\n                <tr>\\n                  <td align=\\"left\\">\\n                    <!-- Replace with your logo image if available -->\\n                    <!-- <img src=\\"https://yourdomain.com/logo.png\\" width=\\"120\\" alt=\\"AIdentX\\" style=\\"display:block;border:0;outline:none;text-decoration:none;\\"> -->\\n                    <div class=\\"logo-txt\\" style=\\"font-family:Segoe UI, Roboto, Arial, sans-serif;font-size:20px;line-height:24px;font-weight:700;color:#ffffff;letter-spacing:0.3px;\\">\\n                      AIdentX\\n                    </div>\\n                    <div style=\\"height:4px;\\"></div>\\n                    <div class=\\"logo-txt\\" style=\\"font-family:Segoe UI, Roboto, Arial, sans-serif;font-size:12px;line-height:16px;color:#e6f6f6;opacity:0.9;\\">\\n                      Unified. Intelligent. Automated.\\n                    </div>\\n                  </td>\\n                </tr>\\n              </table>\\n            </td>\\n          </tr>\\n\\n          <!-- Body -->\\n          <tr>\\n            <td class=\\"text\\" style=\\"padding:28px 24px 8px 24px;font-family:Segoe UI, Roboto, Arial, sans-serif;color:#12232e;\\">\\n              <h1 style=\\"margin:0 0 12px 0;font-size:20px;line-height:26px;font-weight:700;color:#12232e;\\">\\n                Role Assignment Notification\\n              </h1>\\n              <p style=\\"margin:0 0 12px 0;font-size:15px;line-height:22px;\\">\\n                Dear <strong>${username}</strong>,\\n              </p>\\n              <p style=\\"margin:0 0 16px 0;font-size:15px;line-height:22px;\\">\\n                You have been assigned to the <strong>${roleName}</strong> role in AIdentX.\\n              </p>\\n\\n              <!-- Info box -->\\n              <table role=\\"presentation\\" width=\\"100%\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"margin:12px 0 16px 0;\\">\\n                <tr>\\n                  <td style=\\"background:#eaf6f6;border:1px solid #c9e7e7;border-radius:10px;padding:14px 16px;\\">\\n                    <p style=\\"margin:0;font-family:Segoe UI, Roboto, Arial, sans-serif;font-size:14px;line-height:20px;color:#0f3d3d;\\">\\n                      If you didn’t expect this change, please contact your administrator or the IAM team immediately.\\n                    </p>\\n                  </td>\\n                </tr>\\n              </table>\\n\\n              <!-- Next steps -->\\n              <p style=\\"margin:0 0 8px 0;font-size:14px;line-height:20px;font-weight:600;\\">Next steps</p>\\n              <ul style=\\"margin:0 0 16px 22px;padding:0;font-size:14px;line-height:21px;\\">\\n                <li>Review the access granted by this role.</li>\\n                <li>Complete any required attestations or training.</li>\\n                <li>Report unexpected access to the IAM team.</li>\\n              </ul>\\n\\n              <!-- Button -->\\n              <table role=\\"presentation\\" cellpadding=\\"0\\" cellspacing=\\"0\\" border=\\"0\\" style=\\"margin:8px 0 20px 0;\\">\\n                <tr>\\n                  <td align=\\"left\\">\\n                    <a class=\\"btn\\" href=\\"https://your-aidentx-portal.example/roles/${roleName}\\"\\n                       style=\\"display:inline-block;background:#348B8B;border:1px solid #2f7a7a;border-radius:8px;padding:12px 18px;\\n                              font-family:Segoe UI, Roboto, Arial, sans-serif;font-size:14px;line-height:16px;text-decoration:none;\\n                              color:#ffffff;font-weight:600;\\">\\n                      View Role Details\\n                    </a>\\n                  </td>\\n                </tr>\\n              </table>\\n\\n              <hr class=\\"divider\\" style=\\"border:none;border-top:1px solid #e6eef5;margin:8px 0 16px 0;\\" />\\n\\n              <!-- Meta / Support -->\\n              <p class=\\"muted\\" style=\\"margin:0 0 6px 0;font-size:12px;line-height:18px;color:#5b6b7c;\\">\\n                Notification ID: <span style=\\"color:#348B8B;\\">${notificationId}</span> &nbsp;•&nbsp; Date: ${date}\\n              </p>\\n              <p class=\\"muted\\" style=\\"margin:0 0 0 0;font-size:12px;line-height:18px;color:#5b6b7c;\\">\\n                Need help? Contact the IAM team at <a href=\\"mailto:iam-support@aidentx.com\\" style=\\"color:#448BC5;text-decoration:none;\\">iam-support@aidentx.com</a>.\\n              </p>\\n            </td>\\n          </tr>\\n\\n          <!-- Footer -->\\n          <tr>\\n            <td style=\\"padding:18px 24px 24px 24px;\\">\\n              <table role=\\"presentation\\" width=\\"100%\\">\\n                <tr>\\n                  <td align=\\"left\\">\\n                    <p class=\\"muted\\" style=\\"margin:0;font-family:Segoe UI, Roboto, Arial, sans-serif;font-size:11px;line-height:17px;color:#7a8a9a;\\">\\n                      © ${year} AIdentX. All rights reserved.<br/>\\n                      This is an automated message—please do not reply.\\n                    </p>\\n                  </td>\\n                </tr>\\n              </table>\\n            </td>\\n          </tr>\\n\\n        </table>\\n        <!-- End main container -->\\n      </td>\\n    </tr>\\n  </table>\\n</body>\\n</html>\\n", "isEnabled": true, "triggerType": "ASSIGN_INTERNAL_ROLE", "templateName": "Assign role", "templateSubject": "Assigning role ${email}!"}	c6e7730e-1d2f-46f8-943a-c369f3281356	Template Manager	low	{"language": "EN_UK", "emailBody": "<!DOCTYPE html>\\n<html lang=\\"en\\" style=\\"margin:0;padding:0;\\">\\n<head>\\n  <meta charset=\\"UTF-8\\" />\\n  <meta name=\\"viewport\\" content=\\"width=device-width\\" />\\n  <meta http-equiv=\\"X-UA-Compatible\\" content=\\"IE=edge\\" />\\n  <title>AIdentX Notification</title>\\n  <style>\\n    /* Some clients respect embedded CSS for dark mode */\\n    @media (prefers-color-scheme: dark) {\\n      .bg-body { background-color:#0f1a1a !important; }\\n      .card     { background-color:#112424 !important; border-color:#1f3a